      if (!isIntInRange(command.qty, 1)) return reject('BAD_AMOUNT', 'qty must be an integer >= 1');
      if (!isIntInRange(command.unitPriceCents, 0)) {
        return reject('BAD_AMOUNT', 'unitPriceCents must be an integer >= 0');
      }
    }
    if (command.type === 'pay') {
      if (!isIntInRange(command.amountCents, 0)) return reject('BAD_AMOUNT', 'amountCents must be an integer >= 0');
    }
    if (command.type === 'refund') {
      if (!isIntInRange(command.amountCents, 1)) return reject('BAD_AMOUNT', 'amountCents must be an integer >= 1');
    }

