        this.#paidCents = command.amountCents;
        to = 'paid';
        break;
      case 'pack':
        to = 'packed';
        break;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        to = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = at;
        to = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        to = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        to = this.#refundedCents >= this.#paidCents ? 'refunded' : 'delivered';
        break;
      default:
        break;
    }

    this.#state = to;

    const seq = this.#audit.length + 1;
    this.#audit.push({
      seq,
      commandId: command.commandId,
      type: command.type,
      at,
      from,
      to,
      ok: true,
    });
    const result = { ok: true, state: this.#state, seq, replayed: false };
    this.#byCommandId.set(command.commandId, result);
    return result;
  }

